    const blobs = [
      { x: 300 + Math.sin(state.elapsed * 0.02) * 12, y: 180, r: 260, c: palette.accent },
      { x: 980, y: 540 + Math.cos(state.elapsed * 0.015) * 10, r: 300, c: palette.accentSoft },
