      context.fill();
      context.fillStyle = 'rgba(0,0,0,0.25)';
      for (const crater of craters[index]) {
        context.beginPath();
        context.arc(
          planet.x + Math.cos(crater.a) * crater.d * planet.radius,
          planet.y + Math.sin(crater.a) * crater.d * planet.radius,
          crater.r, 0, Math.PI * 2,
